use std::{env,fs,process::Command};
use uor_r4_tokenizer::{ByteBpeTokenizer,dialogue::{DialogueProtocol,Message}};
fn main()->Result<(),Box<dyn std::error::Error>> {let a:Vec<String>=env::args().collect(); let root=&a[1]; let mode=&a[2]; let tok=ByteBpeTokenizer::from_tokenizer_json_bytes(&fs::read("/home/callard/uor-codex/20261118-diagnostics/inputs/tokenizer.json")?).ok_or("tokenizer")?; let p=DialogueProtocol::literal_roles_v2(&tok)?; let enc=p.bind(&tok)?;
if mode=="prepare" {fs::create_dir_all(format!("{root}/scripts"))?;let contexts=[("I currently live in amber compass. My current job is indigo harbor.","indigo harbor","amber compass","dual-p1-a1-o1-job-familiar"),("I currently live in emerald river. My current job is ivory mountain.","ivory mountain","emerald river","dual-p3-a0-o1-job-familiar"),("I currently live in golden valley. My current job is scarlet garden.","scarlet garden","golden valley","dual-p2-a0-o1-job-familiar"),("I currently live in ivory mountain. My current job is emerald river.","emerald river","ivory mountain","dual-p3-a1-o1-job-familiar")];let qs=[("job","familiar-a","Just checking. What is my current job?"),("job","familiar-b","For clarity. What is my current job?"),("job","new","A quick reminder: Which job do I have now?"),("home","familiar","One more thing. Where do I currently live?")];let mut rows=Vec::new();let mut spans=Vec::new();for (i,(first,job,home,prior)) in contexts.iter().enumerate(){for (w,(role,wording,q)) in qs.iter().enumerate(){let id=format!("supp-p{i}-w{w}");let row=json!({"id":id,"role":role,"cohort":"historical-dual-enriched","wording":wording,"value":if *role=="job"{job}else{home},"turns":[first,q],"answer":if *role=="job"{format!(" Your job is {job}.")}else{format!(" You live in {home}.")},"prior_id":prior});let js=first.find("My current job is ").unwrap()+"My current job is ".len();let je=first[js..].find('.').unwrap()+js;let prompt=enc.encode_assistant_prefix(&[Message{role:"user",content:first}]).tokens;let mut start=None;let mut end=None;for k in 1..=prompt.len(){let decoded=tok.decode(&prompt[..k]);let target=format!("User: {first}");let full=decoded.strip_prefix("<|bos|>").unwrap_or(&decoded);if target.starts_with(full){let n=full.len();let s="User: ".len()+js;let e="User: ".len()+je;if start.is_none()&&n>s{start=Some(k-1)}if end.is_none()&&n>=e{end=Some(k)}}}spans.push(json!({"id":id,"job_value_start":start.ok_or("start")?,"job_value_end":end.ok_or("end")?,"job_value":job,"first_prompt_ids":prompt}));let script=json!({"schema":"uor-r4.chat-script/1","turns":[{"user":first},{"user":q}]});fs::write(format!("{root}/scripts/{id}.json"),serde_json::to_vec_pretty(&script)?)?;rows.push(row);}}fs::write(format!("{root}/manifest.json"),serde_json::to_vec_pretty(&rows)?)?;fs::write(format!("{root}/source-spans.json"),serde_json::to_vec_pretty(&spans)?)?;}
else if mode=="capture" {fs::create_dir_all(format!("{root}/transcripts"))?;fs::create_dir_all(format!("{root}/stderr"))?;let rows:Vec<Value>=serde_json::from_slice(&fs::read(format!("{root}/manifest.json"))?)?;for row in rows {let id=row["id"].as_str().unwrap();let out=Command::new("/mnt/plexpool/uor-r4-corpus/runs/20261121-orderfree-trunk/integrated-client-v1/integrated-features-target/release/uor-chat").args(["--discrete","/mnt/plexpool/uor-r4-corpus/runs/20261121-orderfree-trunk/codex-reader/order-free-seed1.d11","--tokenizer","/home/callard/uor-codex/20261118-diagnostics/inputs/tokenizer.json","--protocol","2","--max-tokens","48","--script",&format!("{root}/scripts/{id}.json")]).output()?;fs::write(format!("{root}/transcripts/{id}.json"),out.stdout)?;fs::write(format!("{root}/stderr/{id}.txt"),out.stderr)?;eprintln!("{id} {}",out.status);}} Ok(())}
